-- ============================================================
-- SEED EXT 5: Módulo 20 — Academic Connectors (ex 218-300) — FINAL
-- Consolidação: AC em essays completos, AC em TOEFL avançado,
-- AC para estruturas retóricas complexas
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'academic-connectors';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo academic-connectors não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: Conectores de estrutura de argumento
  (cid,51,218,'gap_fill','The central _____ of this essay is that digital literacy _____ (constitute) a civic competency rather than merely a technical skill. _____ support _____ claim, we _____ (examine) three bodies of evidence.','contention / constitutes / In / this / will examine',NULL,'Thesis language: contention + in support of this claim + will examine (roadmap).','hard'),
  (cid,51,219,'multiple_choice','Which academic connector introduces the THESIS of an essay MOST effectively?','This essay contends that X, and proceeds to demonstrate this through analysis of Y and Z.','[''This essay is about X and will look at Y and Z.'',''This essay contends that X, and proceeds to demonstrate this through analysis of Y and Z.'',''I will argue that X in this essay.'',''This essay''s main point is that X.'']','Formal academic thesis language: contends that + proceeds to demonstrate.','easy'),
  (cid,51,220,'gap_fill','_____ _____ determining whether intervention was effective, one must first establish _____ _____ intervention _____ (actually/occur/passive) as intended.','In order to / whether the / was actually implemented',NULL,'''In order to + base verb'' + ''whether + clause'' = academic connector for methodology.','hard'),
  (cid,51,221,'gap_fill','The following analysis _____ _____ _____ three dimensions: first, the historical context; second, the economic implications; third, the social consequences.','proceeds along / is organized along / is structured around',NULL,'Essay roadmap: ''proceeds along three dimensions'' = metacommentary connector.','hard'),
  (cid,51,222,'gap_fill','_____ _____ the evidence, several tentative conclusions _____ (draw/passive). _____, the relationship between X and Y _____ (appear) to be non-linear.','On the basis of / can be drawn / Specifically / appears',NULL,'''On the basis of'' + ''can be drawn'' + ''specifically'' = academic conclusion language.','hard'),

  -- BLOCK 52: Conectores para análise causal
  (cid,52,223,'gap_fill','Inequality _____ (not/arise) spontaneously; _____ _____, it _____ (produce/passive) by specific institutional arrangements that _____ (systematically/favor) returns to capital _____ returns to labor.','does not arise / rather / is produced / systematically favor / over',NULL,'''Rather'' = contrast/correction. ''Systematically favor over'' = causal analysis.','hard'),
  (cid,52,224,'gap_fill','The crisis was not _____ _____ a single cause but _____ _____ an accumulation of structural vulnerabilities that _____ (mutually/reinforce/passive) over decades.','attributable to / rather to / had been mutually reinforced',NULL,'''Attributable to'' + ''rather to'' (corrective) = causal redirection connector.','hard'),
  (cid,52,225,'multiple_choice','Which phrase BEST introduces a causal mechanism in academic writing?','The mechanism by which X produces Y operates through a feedback loop in which...','[''X causes Y because of...'',''The mechanism by which X produces Y operates through a feedback loop in which...'',''X leads to Y via...'',''X makes Y happen through...'']','''The mechanism by which X produces Y'' = formal academic causal mechanism language.','hard'),
  (cid,52,226,'gap_fill','_____ _____ _____ between these variables _____ (not/imply) causation; the observed _____ (confound/passive) by a third variable _____ (link) both.','Correlation / does not imply / association / may be confounded / linking',NULL,'''Correlation... does not imply causation'' + ''may be confounded'' + ''linking'' = standard academic causal caveat.','hard'),

  -- BLOCK 53: Conectores para contraste retórico avançado
  (cid,53,227,'multiple_choice','What does ''while'' at the START of a sentence (not mid-sentence) typically introduce in academic writing?','A concessive clause acknowledging one fact before contrasting it with another.','[''A time clause'',''A concessive clause acknowledging one fact before contrasting it with another.'',''A result clause'',''A condition'']','''While X is true, Y is also the case'' = concessive academic connector.','medium'),
  (cid,53,228,'gap_fill','While _____ _____ _____ (argue/passive) that globalization reduces poverty, a growing body of evidence _____ (suggest) that its distributional consequences _____ (be) deeply uneven.','it is often argued / suggests / are',NULL,'''While it is often argued that'' = acknowledging opposing view + connector to contrasting claim.','hard'),
  (cid,53,229,'gap_fill','_____ some scholars _____ (discount) the significance of cultural factors in economic development, others _____ (insist) that institutions, in turn, _____ (embed/passive) in cultural frameworks that _____ (shape) their operation.','Whereas / dismiss/discount / insist / are embedded / shape',NULL,'''Whereas'' = contrast between two scholarly positions.','hard'),
  (cid,53,230,'gap_fill','The data _____ (support) the hypothesis in the short term; _____ _____ long term, however, the picture _____ (reverse/passive).','support / in the / is reversed / was reversed',NULL,'''In the long term, however'' = temporal contrast connector.','medium'),

  -- BLOCK 54: Conectores para síntese e conclusão
  (cid,54,231,'gap_fill','_____ _____ the foregoing analysis, it _____ (appear) that simple solutions are unlikely to be effective — the problem _____ (require) a multi-dimensional response.','In light of / appears / requires',NULL,'''In light of the foregoing'' = retrospective synthesis connector.','medium'),
  (cid,54,232,'gap_fill','The _____ _____ _____ evidence suggests that the proposed mechanism is plausible, though it _____ (not/constitute) conclusive proof.','weight of the / does not constitute',NULL,'''The weight of the evidence suggests'' = synthesis connector for evaluating body of research.','hard'),
  (cid,54,233,'multiple_choice','Which connector is BEST suited for the FINAL SENTENCE of a TOEFL essay conclusion?','Ultimately, the evidence suggests that while the challenges are significant, they are not insurmountable with appropriate policy investment.','[''As a result, the evidence suggests challenges are significant.'',''Ultimately, the evidence suggests that while the challenges are significant, they are not insurmountable with appropriate policy investment.'',''In conclusion, the evidence suggests that challenges are significant and insurmountable.'',''Furthermore, the evidence suggests that challenges are significant.'']','''Ultimately'' = synthesis-conclusion connector appropriate for essay ending.','easy'),
  (cid,54,234,'gap_fill','_____ _____ _____, this essay has argued that the relationship between X and Y is shaped primarily by institutional context rather than by the inherent characteristics of either variable _____ _____.','In summary / in isolation / on its own',NULL,'''In summary'' + ''in isolation/on its own'' = standard academic conclusion language.','hard'),

  -- BLOCK 55: TOEFL Reading
  (cid,55,235,'multiple_choice','[TOEFL Reading] ''Although this approach has merit, it nonetheless overlooks several critical factors.'' The connector ''nonetheless'' signals:','A concession followed by a qualification — acknowledging merit but maintaining opposition.','[''An example'',''Additional support'',''A concession followed by a qualification — acknowledging merit but maintaining opposition.'',''A definition'']','''Nonetheless'' = concessive: I accept the merit, but I still disagree on these points.','medium'),
  (cid,55,236,'gap_fill','[TOEFL Reading] ''GDP _____ _____ an imperfect measure of economic welfare; _____ _____, it _____ (remain) the most widely used because of its administrative simplicity.'' Best forms?','is admittedly / even so / remains',NULL,'''Admittedly'' (concession) + ''even so'' (maintaining opposition) + PS.','hard'),
  (cid,55,237,'multiple_choice','[TOEFL Reading] ''The evidence, taken as a whole, points toward a moderate rather than a strong effect.'' The phrase ''taken as a whole'' functions as:','A connector signaling that the conclusion synthesizes multiple pieces of evidence.','[''A condition'',''An example'',''A connector signaling that the conclusion synthesizes multiple pieces of evidence.'',''A contrast'']','''Taken as a whole'' = synthesis connector for evaluating a body of evidence.','medium'),

  -- BLOCK 56: TOEFL Speaking
  (cid,56,238,'production','[TOEFL Speaking — 45s] A reading and lecture discuss urban congestion solutions. Summarize using academic connectors: while, although, however, consequently, in turn, moreover.','',NULL,'The reading argues that road pricing — charging drivers for using congested roads at peak times — is the most efficient mechanism for reducing urban traffic congestion, citing evidence from London and Stockholm where such schemes have reduced congestion substantially. While the empirical evidence for road pricing''s effectiveness is broadly accepted, the lecture introduces several important qualifications. Although road pricing achieves congestion reduction, its distributional effects are contested: congestion charges impose a greater proportional burden on lower-income commuters who cannot easily afford alternative transport. Consequently, the lecture argues that pricing schemes should be accompanied by substantial investment in public transport alternatives, which would in turn reduce the regressive impact. Moreover, the professor notes that the political feasibility of road pricing is highly sensitive to how revenues are used — schemes that recycle revenue into visible public transport improvements have proved more sustainable than those where the revenue benefits are less tangible to commuters.','hard'),
  (cid,56,239,'production','[TOEFL Speaking — 60s] Discuss the concept of global governance. Use academic connectors for structure, contrast, addition, and conclusion.','',NULL,'Global governance refers to the collective management of transnational challenges through institutions, norms, and cooperative arrangements that extend beyond the authority of any single state. At first glance, the concept raises a fundamental tension: sovereign states retain ultimate authority within their borders, and yet many of the most significant contemporary challenges — climate change, pandemic disease, financial instability, cyber threats — cannot be managed effectively without cooperation that transcends sovereignty. In practice, global governance operates through a complex and fragmented architecture that includes formal international organizations such as the United Nations and WTO, informal groupings such as the G20, bilateral and multilateral treaties, and private governance mechanisms developed by industry associations and NGOs. While this system lacks the coherence and enforcement capacity of domestic governance, it has nonetheless produced significant outcomes in areas such as trade liberalization, nuclear non-proliferation, and the coordination of monetary policy during the 2008-9 financial crisis. However, the weaknesses of the system are increasingly visible: climate negotiations have produced commitments that fall well short of what the physics of the atmosphere requires, the WHO has struggled to enforce information-sharing obligations on powerful member states, and geopolitical competition is undermining multilateral institutions that were built for a more cooperative era. Ultimately, whether global governance can be strengthened sufficiently to manage twenty-first century transnational challenges represents one of the most important political questions of our time.','hard'),

  -- BLOCK 57: Production essay tasks final
  (cid,57,240,'production','[TOEFL Writing — 200 words] Write a body paragraph on the merits and limitations of GDP as a welfare measure. Use at least 8 academic connectors across their different functions.','',NULL,'GDP has long served as the primary summary measure of economic activity, and in this function it remains genuinely useful. In the first place, it is administratively tractable: governments collect the necessary data as a byproduct of tax and trade administration, and the methodology is standardized across countries, making international comparisons possible. Moreover, GDP growth correlates positively with improvements in many dimensions of welfare — particularly in low-income contexts where poverty is income-constrained. Nonetheless, GDP has fundamental limitations as a measure of welfare that have been extensively documented. To begin with, it records market transactions regardless of their contribution to human wellbeing: an increase in car accidents, for instance, boosts GDP through medical and repair spending, while volunteer work, domestic labor, and environmental services provide immense value without entering the measure. Furthermore, GDP is insensitive to distribution: rapid growth that benefits primarily the wealthy while leaving median incomes stagnant produces the same aggregate figure as broadly shared growth. In light of these limitations, several alternative indices — most notably the UNDP''s Human Development Index and the OECD Better Life Index — have been developed. While these alternatives remain imperfect and contested, they represent meaningful advances in measuring what economic activity is ultimately for: the expansion of human capabilities and the reduction of suffering.','hard'),
  (cid,57,241,'production','[TOEFL Writing — 200 words] Write a body paragraph on the digital divide. Use academic connectors to structure argument, introduce evidence, concede objections, and conclude.','',NULL,'The digital divide — the gap between those with adequate access to digital technology and those without — operates at multiple scales simultaneously and resists simple characterization or simple solutions. At the international level, access to high-speed internet remains profoundly unequal: while penetration rates exceed 90% in North America, Western Europe, and parts of East Asia, they remain below 30% in many sub-Saharan African countries, partly as a result of inadequate infrastructure investment and partly because of cost barriers that make mobile data prohibitively expensive relative to local incomes. Within high-income countries, meanwhile, the divide manifests not merely as a binary of access versus non-access but as a gradient of quality, reliability, and digital skills. That said, progress has been substantial: mobile phone penetration has expanded dramatically in low-income countries over the past decade, and several initiatives — including subsidized device programs and zero-rated educational content — have reduced access barriers for specific populations. However, progress in physical access has not been matched by equivalent progress in digital literacy: mere access to devices and connectivity does not translate automatically into productive use, particularly in educational and economic contexts. In sum, addressing the digital divide requires attention to infrastructure, cost, literacy, and the quality and relevance of available content simultaneously.','hard'),
  (cid,57,242,'production','[TOEFL Writing — 200 words] Write a concluding paragraph for a TOEFL essay on nuclear energy''s role in addressing climate change. Use connectors for synthesis, concession, and recommendation.','',NULL,'This essay has examined the arguments for and against the expansion of nuclear energy as a strategy for reducing greenhouse gas emissions, and the evidence does not support a simple conclusion in either direction. On the one hand, the low lifecycle carbon emissions of nuclear power make it, in principle, a valuable tool in the transition away from fossil fuels, and the experience of countries such as France demonstrates that a largely nuclear electricity system can be operated safely and reliably at scale. On the other hand, the financial economics of new nuclear construction have become deeply problematic in most Western markets: several large projects have experienced severe cost overruns and delays that have made them substantially more expensive than renewable alternatives, at least in contexts with adequate grid flexibility and storage. Furthermore, the unresolved question of long-term radioactive waste disposal represents a genuine intergenerational challenge that requires honest acknowledgment rather than deferral. In light of these considerations, it appears that nuclear energy may be valuable as part of a diversified low-carbon portfolio in contexts where geography limits renewable deployment, but that it is unlikely to represent the most cost-effective path to decarbonization in most settings. Ultimately, the case for or against nuclear expansion should be made on a context-specific basis rather than through ideological commitment in either direction.','hard'),

  -- BLOCK 58: Exercícios finais 243-300
  (cid,58,243,'gap_fill','_____ _____ the accumulated evidence, the panel _____ (conclude) that the intervention _____ (more/likely/effective/not) in high-intensity contexts.','On balance / concluded / was more likely effective / not',NULL,'''On balance'' = weighing connector for evaluative synthesis.','hard'),
  (cid,58,244,'production','[TOEFL Writing — 200 words] Write a paragraph on the relationship between trade and economic development. Use at least 8 different academic connectors.','',NULL,'The relationship between international trade and economic development has been one of the most debated topics in development economics since the mid-twentieth century. In the first place, standard trade theory predicts mutual gains from specialization according to comparative advantage: countries that open to trade should achieve higher income levels than they would under autarky. Empirically, furthermore, the rapid economic growth of East Asian economies — initially Japan, then South Korea and Taiwan, subsequently China and Vietnam — has been associated with export-led development strategies, suggesting a positive link between trade openness and development. Nevertheless, correlation does not imply causation, and researchers who have examined the evidence more carefully note that the most successful developers did not simply liberalize trade but rather managed their integration into the global economy through industrial policy, infant industry protection, and investment in education and infrastructure. In other words, the mechanism of trade-and-development is not automatic but depends critically on complementary domestic institutions and policies. By contrast, countries that liberalized rapidly in response to external pressure in the 1980s and 1990s experienced highly variable outcomes, with many seeing deindustrialization rather than structural transformation. The evidence therefore suggests that trade is a potentially powerful instrument for development, but that the conditions under which it delivers on this potential are more demanding than simple trade liberalization accounts acknowledge.','hard'),
  (cid,58,245,'production','[TOEFL Speaking — 60s] Discuss what you see as the most important global challenge of the next 50 years. Use academic connectors to structure your argument formally.','',NULL,'Of the many transnational challenges that humanity will confront over the coming half century, the maintenance of a stable climate appears to me to be the most fundamental, in the sense that its resolution is a precondition for addressing many other challenges effectively. In the first place, the physical consequences of unmanaged climate change — rising sea levels, increased frequency and severity of extreme weather events, disruption to agricultural systems, and the accelerated loss of biodiversity — will intensify existing pressures on food security, water availability, and human health in ways that disproportionately affect the populations least responsible for emissions. Moreover, climate change is a stress multiplier: it will exacerbate conflicts over resources, trigger large-scale migration flows that existing political and legal frameworks are not designed to manage, and undermine the economic foundations of development in the most vulnerable regions. By contrast, the technological pathways to decarbonization are already clear in broad outline: renewable energy is now cost-competitive with fossil fuels in most markets, and the remaining barriers are primarily political and institutional rather than technical. In light of this, the central challenge is not whether solutions exist but whether the political systems of major emitting countries can generate the sustained and coordinated action that the physics of the climate system requires. Ultimately, addressing climate change is less a technical problem than a problem of collective action under conditions of geopolitical competition — and that is what makes it so difficult.','hard'),
  (cid,58,246,'production','[TOEFL Writing — 200 words] Write a paragraph on multiculturalism as a social policy. Use academic connectors for structure, concession, addition, and conclusion.','',NULL,'Multiculturalism, as a framework for managing cultural diversity in pluralist societies, has attracted both enthusiastic advocacy and fierce criticism since it gained policy prominence in the 1970s and 1980s. In the first place, proponents argue that recognizing and accommodating cultural difference within a shared civic framework enables immigrant and minority communities to participate fully in public life without being required to abandon the cultural identities that provide them with meaning and community belonging. Moreover, research on minority well-being suggests that recognition policies are associated with stronger integration outcomes in education and labor markets than assimilationist approaches, which create psychological costs for those who must choose between cultural authenticity and social participation. Notwithstanding these arguments, critics from both left and right have raised serious objections. From the left, scholars such as Brian Barry have argued that multiculturalism risks creating separate community spheres that reduce interaction across cultural lines and weaken the common bonds of democratic citizenship. From the right, critics contend that cultural accommodation enables practices incompatible with liberal values to persist under the protection of group rights. In light of these tensions, most contemporary policy scholars advocate a civic integration model that recognizes cultural difference while maintaining clear commitments to shared constitutional values — a position that attempts to navigate between assimilation and unlimited pluralism.','hard'),
  (cid,58,247,'gap_fill','The study''s methodology was _____ _____, it _____ (not/allow) causal inference, and _____ _____, the implications for policy _____ (must/state) with appropriate caution.','observational; therefore / did not allow / as such / must be stated',NULL,'''Observational; therefore'' + ''did not allow'' + ''as such'' = academic caveat connector chain.','hard'),
  (cid,58,248,'production','[TOEFL Writing — 200 words] Write a body paragraph on the legacy of colonialism in development. Use at least 8 academic connectors.','',NULL,'The legacy of European colonialism continues to shape economic development outcomes in formerly colonized nations, and understanding this legacy is essential to explaining contemporary patterns of inequality that persist long after formal independence was achieved. In the first place, colonial economic policies were designed to extract value from colonized territories rather than to promote their development: agriculture was oriented toward export commodities rather than food security, manufacturing was suppressed to protect metropolitan industries, and infrastructure was built to serve resource extraction rather than to connect economic centers within the territory. As a result, most formerly colonized nations inherited economic structures at independence that were ill-suited to industrialization and that created enduring path dependencies. Furthermore, colonial boundary-drawing frequently divided existing social and cultural communities and united disparate groups within administrative units, creating post-independence states that lacked the internal cohesion necessary for stable governance. That said, the colonial legacy is not a static constraint, and a number of post-colonial states have achieved significant economic development through policy innovation and institutional reform. Moreover, the relationship between colonial history and contemporary development varies considerably across regions and former colonial powers, suggesting that the mechanisms through which colonialism affects outcomes are multiple and context-dependent. In light of the evidence, acknowledging the colonial legacy appears not only historically accurate but also analytically necessary for understanding development pathways.','hard'),
  (cid,58,249,'production','[TOEFL Writing — 200 words] Write a final essay body paragraph on the ethics of artificial intelligence. Use at least 8 academic connectors.','',NULL,'The ethical governance of artificial intelligence requires that societies resolve a set of tensions that conventional regulatory frameworks were not designed to address. In the first place, AI systems are developed at a pace that consistently outstrips the capacity of regulatory institutions to evaluate and respond: by the time a governance framework is designed, consulted upon, and enacted, the technological frontier has frequently moved beyond the situations the framework was built to address. Furthermore, the harms caused by AI systems are often diffuse and probabilistic rather than acute and traceable to specific actors, making attribution difficult and compensation uncertain. Notwithstanding these challenges, the case for meaningful governance is compelling: automated systems are already making or influencing decisions in criminal justice, credit, healthcare, and employment, with documented evidence of bias against underrepresented groups in several applications. On balance, the governance question is not whether AI should be regulated but how regulation can be designed to be adaptive enough to keep pace with technological change. In light of international regulatory developments — particularly the European AI Act — it appears that the emerging consensus favors a risk-proportionate approach in which high-stakes applications face the most rigorous requirements. This approach is imperfect, but it represents a more defensible starting point than either a moratorium or an absence of governance.','hard'),
  (cid,58,250,'production','[TOEFL Speaking — 60s final] Discuss the importance of academic connectors for TOEFL success. Demonstrate their use by integrating them into your answer.','',NULL,'Academic connectors are among the most important tools available to TOEFL test-takers for several interconnected reasons. In the first place, they signal the logical relationships between ideas — the difference between a paragraph that simply lists points and one that argues through them depends largely on the quality of the connectors that link those points. Furthermore, proficient use of a varied range of connectors is a direct indicator of linguistic sophistication that TOEFL raters are trained to recognize and reward in both writing and speaking rubrics. That said, more is not always better: the indiscriminate use of connectors can make writing feel mechanical, and over-hedging with multiple consecutive concessive markers often weakens rather than strengthens an argument. In other words, the goal is not to deploy connectors frequently but to deploy them precisely — to use the connector that best characterizes the actual logical relationship between the ideas it connects. On balance, students who invest time in understanding the semantic differences between connectors that appear superficially similar — nevertheless versus however, furthermore versus moreover, thus versus therefore — will find that their writing becomes not only more cohesive but more intellectually precise. Ultimately, academic connectors are not stylistic ornaments but structural thinking tools: mastering them means mastering the architecture of academic argument itself.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
